APP_BUNDLE="$HOME/Applications/$APP_NAME.app"
# Nombres de la aplicacion hasta la 1.36.0 y hasta la 1.38.0
OLD_APP_BUNDLES=("$HOME/Applications/Gestor de versiones PHP.app" "$HOME/Applications/Nexum Stack.app")
APP_OPENER="$LOG_DIR/abrir.command"
CMD_DIR="$HOMEBREW_PREFIX/bin"

# ¿Es <script> otro lvm-instalador.sh de una version mas nueva que esta? Entonces no se reapunta a
# esta (seria volver atras sin querer)
function script_is_newer() {
    local v
    [ -n "$1" ] && [ -f "$1" ] && [ "$(realpath_f "$1")" != "$SELF" ] || return 1
    v=$(grep -m1 '^APP_VERSION=' "$1" 2> /dev/null | cut -d'"' -f2)
    [[ "$v" =~ ^[0-9]+(\.[0-9]+)*$ ]] || return 1
    python3 -I -c 'import sys; a, b = (tuple(int(x) for x in v.split(".")) for v in sys.argv[1:3]); sys.exit(0 if a > b else 1)' "$v" "$APP_VERSION"
}

# Archivo .command que abre Terminal (la aplicacion lo abre con "open -a Terminal"). Se reescribe
# si el instalador cambia de sitio.
function write_opener() {
    local content="#!/bin/bash
# Abre el panel del $APP_NAME en Terminal (lo usa $APP_BUNDLE)
export LVM_ACCESO=panel
exec /bin/bash '$SELF'"

    mkdir -p -m 700 "$LOG_DIR"
    if [ "$(cat "$APP_OPENER" 2> /dev/null)" != "$content" ]; then
        echo "$content" > "$APP_OPENER"
        chmod 755 "$APP_OPENER"
    fi
}

# Aplicacion de ~/Applications con el icono de PHP: la ventana nativa si se ha podido compilar
# (build_native_app); si no, un script que abre el panel en Terminal
function create_app() {
    local contents="$APP_BUNDLE/Contents"
    local tmp=$(mktemp -d /tmp/lvm-icono-XXXX) size exec=lvm native=0

    mkdir -p "$contents/MacOS" "$contents/Resources" || return 1
    if [ -x "$APP_SRC_DIR/lvm-app" ] || build_native_app; then
        native=1
        exec=lvm-app
        cp -f "$APP_SRC_DIR/lvm-app" "$contents/MacOS/lvm-app"
    else
        rm -f "$contents/MacOS/lvm-app"
    fi
    cat > "$contents/Info.plist" <<EOF
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleName</key><string>$APP_NAME</string>
    <key>CFBundleDisplayName</key><string>$APP_NAME</string>
    <key>CFBundleIdentifier</key><string>dev.hexer.lvm-instalador</string>
    <key>CFBundleExecutable</key><string>$exec</string>
    <key>CFBundleIconFile</key><string>icono</string>
    <key>CFBundlePackageType</key><string>APPL</string>
    <key>CFBundleVersion</key><string>$APP_VERSION</string>
    <key>CFBundleShortVersionString</key><string>$APP_VERSION</string>
    <key>LSMinimumSystemVersion</key><string>12.0</string>
    <key>NSHighResolutionCapable</key><true/>
    <key>ATSApplicationFontsPath</key><string>fuentes</string>
    <key>LVMScript</key><string>$SELF</string>
</dict>
</plist>
EOF
    printf '#!/bin/bash\nexec open -a Terminal "%s"\n' "$APP_OPENER" > "$contents/MacOS/lvm"
    mkdir -p "$contents/Resources/fuentes"
    tr -d ' \n' <<< "$FONT_GOLDMAN_B64" | base64 --decode > "$contents/Resources/fuentes/Goldman-Regular.ttf" 2> /dev/null
    chmod 755 "$contents/MacOS/lvm"

    # Icono: el PNG se amplia a los tamaños que pide macOS y se convierte a .icns
    tr -d ' \n' <<< "$ICON_PNG_B64" | base64 --decode > "$tmp/icono.png" 2> /dev/null
    mkdir -p "$tmp/icono.iconset"
    for size in 16 32 128 256 512; do
        sips -z $size $size "$tmp/icono.png" --out "$tmp/icono.iconset/icon_${size}x${size}.png" > /dev/null 2>&1
        sips -z $(( size * 2 )) $(( size * 2 )) "$tmp/icono.png" --out "$tmp/icono.iconset/icon_${size}x${size}@2x.png" > /dev/null 2>&1
    done
    iconutil -c icns "$tmp/icono.iconset" -o "$contents/Resources/icono.icns" > /dev/null 2>&1
    rm -rf "$tmp"

    # Firma local (sin certificado), como la que pone el compilador, para el paquete completo
    # Con hardened runtime (-o runtime): macOS no deja cargarle librerias de fuera (DYLD_INSERT_LIBRARIES)
    # ni que otro programa lea su memoria (la contraseña). Si falla, sin el
    codesign --force --deep -o runtime -s - "$APP_BUNDLE" > /dev/null 2>&1 \
        || codesign --force --deep -s - "$APP_BUNDLE" > /dev/null 2>&1
    local stamp="$SELF|$APP_VERSION|$native"
    [ $native -eq 1 ] && stamp+="|$(shasum -a 256 "$APP_SRC_DIR/lvm-app" | cut -d' ' -f1)"
    echo "$stamp" > "$contents/Resources/sello"
    touch "$APP_BUNDLE"
    # Launchpad y el Dock vuelven a leer el paquete (nombre, icono y ejecutable)
    /System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister -f "$APP_BUNDLE" > /dev/null 2>&1
    return 0
}

# ---------------------------------------------------------------- ventana nativa (SwiftUI)

# El codigo de la ventana va dentro de este archivo (swift_source). Se compila en el Mac con las
# herramientas de Xcode (las mismas con las que se compila PHP) y el resultado va dentro de la
# aplicacion de ~/Applications. Si no se puede compilar, la aplicacion abre el panel en Terminal.
APP_SRC_DIR="$LOG_DIR/app"

# Compila la ventana si el codigo ha cambiado. Deja el ejecutable en $APP_SRC_DIR/lvm-app.
# Si falla, el error queda en compilar.log y no se vuelve a intentar con el mismo codigo.
function build_native_app() {
    local src=$APP_SRC_DIR/main.swift bin=$APP_SRC_DIR/lvm-app

    mkdir -p "$APP_SRC_DIR"
    swift_source > "$src.tmp"
    if [ -x "$bin" ] && cmp -s "$src.tmp" "$src"; then
        rm -f "$src.tmp"

        return 0
    fi
    mv -f "$src.tmp" "$src"
    [ -f "$APP_SRC_DIR/fallo.swift" ] && cmp -s "$APP_SRC_DIR/fallo.swift" "$src" && return 1
    command -v xcrun > /dev/null || return 1

    echo "Preparando la ventana del gestor (solo cuando cambia; tarda menos de un minuto)..." >&2
    if xcrun --sdk macosx swiftc -O -parse-as-library -target arm64-apple-macos12.0 \
        -o "$bin.tmp" "$src" > "$APP_SRC_DIR/compilar.log" 2>&1; then
        mv -f "$bin.tmp" "$bin"
        rm -f "$APP_SRC_DIR/fallo.swift"

        return 0
    fi

    rm -f "$bin.tmp" "$bin"
    cp "$src" "$APP_SRC_DIR/fallo.swift"
    echo "No se ha podido compilar la ventana (detalles en $APP_SRC_DIR/compilar.log)." >&2
    echo "El gestor sigue funcionando en Terminal." >&2

    return 1
}

# La aplicacion con el nombre anterior (solo si es la del gestor) pasa a llamarse $APP_NAME: se
# mueve (si aun no esta la nueva) o se borra, y Launchpad deja de enseñarla
function migrate_old_app() {
    local old id lsreg=/System/Library/Frameworks/CoreServices.framework/Frameworks/LaunchServices.framework/Support/lsregister
    [ "$DRY" -eq 1 ] && return 0
    for old in "${OLD_APP_BUNDLES[@]}"; do
        [ -d "$old" ] && [ ! -L "$old" ] || continue
        id=$(/usr/libexec/PlistBuddy -c "Print :CFBundleIdentifier" "$old/Contents/Info.plist" 2> /dev/null)
        [ "$id" == "dev.hexer.lvm-instalador" ] || continue
        "$lsreg" -u "$old" > /dev/null 2>&1
        if [ ! -e "$APP_BUNDLE" ] && mv "$old" "$APP_BUNDLE" 2> /dev/null; then
            # (el sello obliga a rehacerla con el nombre nuevo)
            rm -f "$APP_BUNDLE/Contents/Resources/sello"
        else
            rm -rf "$old"
        fi
    done
    return 0
}

# Pone al dia la aplicacion de ~/Applications (ventana nativa, ruta de este archivo, version)
function update_app() {
    [ -d "$APP_BUNDLE" ] || return 1
    write_opener
    local native=0
    build_native_app && native=1

    local stamp="$SELF|$APP_VERSION|$native"
    [ $native -eq 1 ] && stamp+="|$(shasum -a 256 "$APP_SRC_DIR/lvm-app" | cut -d' ' -f1)"
    [ "$(cat "$APP_BUNDLE/Contents/Resources/sello" 2> /dev/null)" == "$stamp" ] && return 0

    create_app
}

# nexum ventana: abre la aplicacion (la crea si no existe)
function open_window() {
    migrate_old_app
    # Tras actualizar (actualizar-gestor) la ventana se abre con el gestor nuevo: el comando nexum, y
    # fuera los de antes (lvm-instalador, y lvm si era de este programa)
    [ "$DRY" -eq 0 ] && [ "$SELF" == "$TRUSTED_SCRIPT" ] && point_commands
    # La pagina de web.local sin proyecto, al dia tras una actualizacion (solo si se puede escribir
    # sin contraseña: si no, al desmontar el proximo proyecto)
    [ -w "$HTDOCS_DIR/$EMPTY_PROJECT/index.html" ] && empty_page "$HTDOCS_DIR/$EMPTY_PROJECT" > /dev/null 2>&1
    [ -d "$APP_BUNDLE" ] || { write_opener; create_app; }
    update_app
    if [ ! -x "$APP_BUNDLE/Contents/MacOS/lvm-app" ]; then
        if command -v xcrun > /dev/null; then
            echo "La ventana no esta disponible: no se ha podido compilar (mira $APP_SRC_DIR/compilar.log)."
        else
            echo "La ventana no esta disponible: faltan las herramientas de Xcode (xcode-select --install)."
        fi
        echo "Mientras tanto puedes usar el panel: nexum"

        return 1
    fi

    if [ "$DRY" -eq 1 ]; then
        # open no pasa variables de entorno: en simulacion se lanza el ejecutable directamente
        LVM_SIMULAR=1 nohup "$APP_BUNDLE/Contents/MacOS/lvm-app" > /dev/null 2>&1 &
    else
        open "$APP_BUNDLE"
    fi
}

# Codigo de la ventana (SwiftUI). No puede contener una linea con solo LVM_SWIFT.
function swift_source() {
    cat <<'LVM_SWIFT'
#@incluir ventana/
LVM_SWIFT
}

function offer_command_install() {
    [ "$DRY" -eq 1 ] && return 0

    # Descargado con el navegador o copiado de un USB puede llegar sin permiso de ejecucion, y el
    # comando nexum es un enlace a este archivo
    [ -x "$SELF" ] || chmod +x "$SELF" 2> /dev/null
    migrate_old_app

    # Una aplicacion creada hasta la 1.0.0 (ejecutable "pvm") abre un .command de la carpeta
    # antigua ~/.pvm-instalador: se vuelve a crear
    if [ -d "$APP_BUNDLE" ] && [ ! -x "$APP_BUNDLE/Contents/MacOS/lvm" ]; then
        rm -rf "$APP_BUNDLE"
        write_opener
        create_app
    fi

    # La aplicacion se pone al dia: ventana nativa, ruta de este archivo y version. No si ya usa una
    # version mas nueva del script (abrir una copia vieja que quede en Descargas no la vuelve atras)
    local current_script
    if [ -d "$APP_BUNDLE" ]; then
        current_script=$(/usr/libexec/PlistBuddy -c "Print :LVMScript" "$APP_BUNDLE/Contents/Info.plist" 2> /dev/null)
        if script_is_newer "$current_script"; then
            echo "Aviso: la aplicacion usa una version mas nueva del gestor ($current_script): no se cambia a esta ($APP_VERSION)"
        else
            update_app
        fi
    fi

    # Comandos pvm-instalador y pvm de las versiones hasta la 1.0.0: se quitan, y lvm-instalador (y
    # lvm, solo si es un enlace a un lvm-instalador.sh), los de hasta la 1.57.10: ahora es nexum. No
    # hace falta sudo en /opt/homebrew/bin
    local link
    for link in "$CMD_DIR/pvm-instalador" "$CMD_DIR/pvm"; do
        [ -L "$link" ] && [[ "$(readlink "$link")" == */[lp]vm-instalador.sh ]] && rm -f "$link"
    done
    # (un lvm-instalador que lleva a una version mas nueva que esta, no: es de esa)
    link=$CMD_DIR/lvm-instalador
    ! { [ -L "$link" ] && script_is_newer "$(readlink "$link")"; } && drop_old_commands
    # nexum que apunta a otro archivo del instalador se reapunta a este
    link=$CMD_DIR/nexum
    [ -L "$link" ] && [ "$(readlink "$link")" != "$SELF" ] \
        && [[ "$(readlink "$link")" == */[lp]vm-instalador.sh ]] && ! script_is_newer "$(readlink "$link")" \
        && ln -sf "$SELF" "$link"

    local marker="$LOG_DIR/.accesos-ofrecidos"
    local need_cmd=0 need_app=0

    command -v nexum > /dev/null || need_cmd=1
    # Si venia de los comandos con pvm, se vuelven a ofrecer aunque ya se ofrecieran
    [ -f "$marker" ] && [ $need_cmd -eq 0 ] && return 0
    [ -d "$APP_BUNDLE" ] || need_app=1
    [ $need_cmd -eq 0 ] && [ $need_app -eq 0 ] && return 0

    mkdir -p -m 700 "$LOG_DIR"
    touch "$marker"

    local text="¿Quieres crear accesos directos para abrir este gestor facilmente?\n\n"
    [ $need_app -eq 1 ] && text+="  - Aplicacion '$APP_NAME' en ~/Applications (Launchpad y Spotlight)\n"
    [ $need_cmd -eq 1 ] && text+="  - Comando 'nexum' en la terminal ('nexum use 8.4'...)\n"
    text+="\nApuntaran a: $SELF\n(no muevas ni borres este archivo despues)"

    ui_yesno "$text" || return 0

    if [ $need_app -eq 1 ]; then
        write_opener
        create_app
    fi

    # En los Mac con Apple Silicon /opt/homebrew/bin ya esta en el PATH y no necesita sudo
    if [ $need_cmd -eq 1 ]; then
        ln -sf "$SELF" "$CMD_DIR/nexum"
    fi

    ui_msg "Accesos creados. A partir de ahora puedes abrir el gestor desde Launchpad o Spotlight ('$APP_NAME') o escribiendo 'nexum' en la terminal."
}

